-- check.lua: validates a module generated by `stellar-fnmatch cdef` under LuaJIT.
--
--   luajit check.lua layouts <module.lua> <slice> <slices>
--   luajit check.lua decls   <module.lua> <slice> <slices>
--
-- layouts: for every type of the slice, the closure is declared and ffi.sizeof of the type and
--          ffi.offsetof of every member (bit position and width for bitfields) must equal the
--          PDB's values in the module.
-- decls:   every function declaration of the slice must parse (ffi.typeof) once its types are
--          declared.
--
-- LuaJIT has room for 65536 ctypes per state, so the work is split into slices, one process
-- each (run_checks.sh). The last line of the output is a summary: `<what> ok <n> fail <n>`.

local ffi = require("ffi")
local what, path, slice, slices = arg[1], arg[2], tonumber(arg[3] or 1), tonumber(arg[4] or 1)
local M = dofile(path)

local declared = {}
local function opaque(c)
    if declared[c] then
        return
    end
    local t = M.types[c] or M.opaque[c]
    if t == nil then
        error("unknown type " .. c)
    end
    if t.kind == "enum" then
        ffi.cdef(t.cdef)
        declared[c] = "full"
        return
    end
    ffi.cdef(string.format("%s %s; typedef %s %s %s;", t.kind, c, t.kind, c, c))
    declared[c] = "opaque"
end

local function full(c)
    if declared[c] == "full" then
        return
    end
    local t = M.types[c]
    if t == nil then
        error("no definition of " .. c)
    end
    for _, d in ipairs(t.deps) do
        full(d)
    end
    for _, r in ipairs(t.refs) do
        opaque(r)
    end
    if t.kind ~= "enum" then
        opaque(c)
    end
    ffi.cdef(t.cdef)
    declared[c] = "full"
end

local function sorted_keys(t)
    local k = {}
    for name in pairs(t) do
        k[#k + 1] = name
    end
    table.sort(k)
    return k
end

local ok, fail, shown = 0, 0, 0
local reasons = {}
local function failed(name, why)
    fail = fail + 1
    local kind = why:match("^(%S+)") or why
    reasons[kind] = (reasons[kind] or 0) + 1
    if shown < 40 then
        shown = shown + 1
        print("FAIL " .. name .. ": " .. why)
    end
end

if what == "layouts" then
    local names = sorted_keys(M.types)
    local members = 0
    for i = slice, #names, slices do
        local c = names[i]
        local t = M.types[c]
        local good, err = pcall(full, c)
        if not good then
            failed(c, "cdef " .. tostring(err))
        elseif t.kind ~= "enum" then
            local ct = ffi.typeof(c)
            local bad
            if ffi.sizeof(ct) ~= t.size then
                bad = string.format("size %s, PDB %d", tostring(ffi.sizeof(ct)), t.size)
            end
            for _, f in ipairs(t.fields or {}) do
                members = members + 1
                local name, off, bp, bl = f[1], f[2], f[4], f[5]
                local o, p, n
                if f.unit then
                    -- a bitfield read through accessors: its unit must be at the PDB offset
                    o = ffi.offsetof(ct, f.unit)
                    p, n = bp, bl
                else
                    o, p, n = ffi.offsetof(ct, name)
                end
                if o == nil then
                    bad = bad or ("member " .. name .. " missing")
                elseif bp then
                    if p == nil or o * 8 + p ~= off * 8 + bp or n ~= bl then
                        bad = bad or string.format("bitfield %s at %d+%s:%s, PDB %d+%d:%d", name, o, tostring(p), tostring(n), off, bp, bl)
                    end
                elseif o ~= off or p ~= nil then
                    bad = bad or string.format("offset %s at %d, PDB %d", name, o, off)
                end
            end
            if bad then
                failed(c, bad)
            else
                ok = ok + 1
            end
        else
            if ffi.sizeof(c) ~= t.size then
                failed(c, string.format("size %d, PDB %d", ffi.sizeof(c), t.size))
            else
                ok = ok + 1
            end
        end
    end
    for k, n in pairs(reasons) do
        print("REASON " .. k .. " " .. n)
    end
    print(string.format("layouts ok %d fail %d members %d", ok, fail, members))
elseif what == "decls" then
    local names = sorted_keys(M.functions)
    for i = slice, #names, slices do
        local name = names[i]
        for j, f in ipairs(M.functions[name]) do
            local good, err = pcall(function()
                for _, d in ipairs(f.deps) do
                    full(d)
                end
                for _, r in ipairs(f.refs) do
                    opaque(r)
                end
                return ffi.typeof(f.decl)
            end)
            if good then
                ok = ok + 1
            else
                failed(string.format("%s #%d", name, j), "typeof " .. tostring(err) .. " in " .. f.decl)
            end
        end
    end
    for k, n in pairs(reasons) do
        print("REASON " .. k .. " " .. n)
    end
    print(string.format("decls ok %d fail %d", ok, fail))
else
    error("usage: luajit check.lua layouts|decls <module.lua> [slice slices]")
end
